173	    }
174	
175	    if (payment.status !== "pending") {
176	      return errorResponse(409, "not_cancelable", `A ${payment.status} payment cannot be canceled`);
177	    }
178	
179	    payment.status = "canceled";
180	    return HttpResponse.json(payment);
181	  }),
